import * as THREE from 'three';
import {
  NO_GESTURE,
  foldRatios,
  readGesture,
  type HandFold,
  type HandGesture,
  type HandJoints,
} from './handGestures';
import { handHoldTilt } from './handHold';

export type Handedness = 'left' | 'right';

/** Wo die Quest-Profile den Menü-Knopf ☰ melden (`ControllerState.menu`). */
export const MENU_BUTTON = 7;

/** Edge-detected button. Events can arrive between frames, so we count them. */
export class ButtonState {
  pressed = false;
  value = 0;
  justPressed = false;
  justReleased = false;
  private downs = 0;
  private ups = 0;

  press(): void {
    this.pressed = true;
    this.downs++;
  }

  release(): void {
    this.pressed = false;
    this.ups++;
  }

  beginFrame(): void {
    this.justPressed = this.downs > 0;
    this.justReleased = this.ups > 0;
    this.downs = 0;
    this.ups = 0;
  }

  reset(): void {
    this.pressed = false;
    this.value = 0;
    this.justPressed = false;
    this.justReleased = false;
    this.downs = 0;
    this.ups = 0;
  }
}

/**
 * **Woran eine Hand ihre Sachen hält** — der Griffraum, wenn es einen gibt,
 * sonst der Zeigestrahl.
 *
 * Diese eine Zeile stand an **dreizehn** Stellen im Projekt, in drei
 * Schreibweisen und unter vier Namen (`gripOf`, `anchorOf`, `handAnchor`,
 * `handPosition`). Sie ist keine Bequemlichkeit, sondern eine Entscheidung:
 * Ein Controller meldet beides, eine bloße Hand nur den Zeigestrahl — und wer
 * das nicht abfängt, hängt sein Werkzeug bei getrackten Händen an einen Raum,
 * der auf `(0,0,0)` steht und unsichtbar bleibt.
 *
 * Wo bewusst etwas anderes gilt, steht es weiter ausgeschrieben: `updateHold`
 * schließt bloße Hände ausdrücklich aus, und der Eingaberaum zeigt das
 * Handmodell selbst an.
 */
export function gripAnchor(controller: ControllerState): THREE.Object3D {
  return controller.grip.visible ? controller.grip : controller.targetRay;
}

/**
 * **Das Handgelenk, wenn es eines gibt** — sonst derselbe Griffraum wie oben.
 *
 * Der Unterschied zu `gripAnchor` ist eine Sache und eine wichtige: Bei einer
 * getrackten Hand hängt hier etwas am **Handgelenk** statt am Zeigestrahl, und
 * das ist der Unterschied zwischen einer Palette, die neben der Hand
 * mitschwebt, und einer, die vor ihr her fliegt. `null`, solange das Gelenk
 * nicht gesehen wird — daran erkennt der Aufrufer, dass er gerade nichts
 * anzeigen soll.
 */
export function wristAnchor(controller: ControllerState): THREE.Object3D | null {
  if (controller.isHand) {
    const wrist = controller.hand.joints['wrist'];
    return wrist && wrist.visible ? wrist : null;
  }
  return gripAnchor(controller);
}

export class ControllerState {
  handedness: Handedness | null = null;
  connected = false;
  /** True while this input source is a tracked hand instead of a controller. */
  isHand = false;
  inputSource: XRInputSource | null = null;

  readonly trigger = new ButtonState();
  readonly squeeze = new ButtonState();
  /** Pinch (hand tracking) or the trigger of a controller — the generic "select". */
  readonly select = new ButtonState();
  readonly primary = new ButtonState(); // A / X
  readonly secondary = new ButtonState(); // B / Y
  /**
   * **☰ am linken Controller** — der Menü-Knopf unter dem Stick.
   *
   * Im Standard-Mapping (`xr-standard`) gibt es ihn nicht; die Quest-Profile
   * ab der Quest 2 melden ihn aber als `buttons[7]`
   * (`public/controllers/…/profile.json`, Bauteil `menu`). Die Quest 1
   * (`oculus-touch-v2`) und die rechte Hand (dort sitzt der Meta-Knopf, der
   * dem System gehört) melden keine siebte Nummer — dann bleibt er einfach
   * still, und das Menü geht wie immer über den Knopf am Handgelenk auf.
   */
  readonly menu = new ButtonState();
  /** The stick pressed in like a button — sprint on the left, crouch on the right. */
  readonly stick = new ButtonState();
  readonly thumbstick = new THREE.Vector2();
  /**
   * **Der Knoten, an dem hängt, was diese Hand hält** — Werkzeug wie
   * Gegenstand.
   *
   * Am Controller ist er der *Griffraum* der Brille und sonst nichts: er sitzt
   * darin, ohne ihn zu drehen, und alles bleibt, wie es war. Eine **getrackte
   * Hand** hat keinen Griffraum (three.js lässt ihn stehen, weil eine Hand
   * keine `gripSpace` meldet), also sitzt er dort im Zeigestrahl — und um den
   * gemessenen Versatz gedreht, damit ein Gegenstand aufrecht in der Faust
   * liegt und ein Werkzeug dorthin zielt, wohin die Hand zeigt
   * (`handHold.ts`).
   *
   * Er steht **immer am selben Ort** wie der Raum, in dem er hängt — gedreht
   * wird, nicht verschoben. Wer nur wissen will, *wo* eine Hand ist, bekommt
   * hier also dieselbe Antwort wie vorher.
   */
  readonly hold = new THREE.Group();
  /** Index fingertip object, provided by the hand visuals. */
  fingertip: THREE.Object3D | null = null;
  /**
   * How far each finger of a tracked hand is folded onto the palm, in palm
   * lengths. Null for a controller — and the raw material behind `gesture`,
   * kept because the hand-and-controller world puts the numbers on the wall.
   */
  fold: HandFold | null = null;
  /** What a tracked hand is doing: closing around something, pulling, both. */
  gesture: HandGesture = { ...NO_GESTURE };

  constructor(
    readonly index: number,
    readonly targetRay: THREE.Group,
    readonly grip: THREE.Group,
    readonly hand: THREE.XRHandSpace,
  ) {}

  /** True when the pose of this input source is currently tracked. */
  get tracked(): boolean {
    return this.connected && (this.isHand ? this.hand.visible : this.targetRay.visible);
  }

  /** Origin + direction of the pointing ray, in world space. */
  getRay(target: THREE.Ray): THREE.Ray {
    this.targetRay.getWorldPosition(target.origin);
    target.direction
      .set(0, 0, -1)
      .applyQuaternion(this.targetRay.getWorldQuaternion(_quat))
      .normalize();
    return target;
  }

  /** World position of the index fingertip, when the hand is tracked. */
  getFingertip(target: THREE.Vector3): THREE.Vector3 | null {
    if (this.fingertip) return this.fingertip.getWorldPosition(target);
    if (!this.targetRay.visible) return null;
    // Fallback before the hand visuals had a chance to run.
    this.targetRay.getWorldPosition(target);
    return target.add(
      _vec.set(0, 0, -0.06).applyQuaternion(this.targetRay.getWorldQuaternion(_quat)),
    );
  }

  /** Short haptic pulse, ignored when the runtime has no actuator. */
  pulse(intensity = 0.4, durationMs = 30): void {
    const actuators = (
      this.inputSource?.gamepad as
        { hapticActuators?: Array<{ pulse?: (i: number, d: number) => void }> } | undefined
    )?.hapticActuators;
    actuators?.[0]?.pulse?.(intensity, durationMs);
  }

  reset(): void {
    this.connected = false;
    this.isHand = false;
    this.inputSource = null;
    this.trigger.reset();
    this.squeeze.reset();
    this.select.reset();
    this.primary.reset();
    this.secondary.reset();
    this.stick.reset();
    this.menu.reset();
    this.thumbstick.set(0, 0);
    this.fingertip = null;
    this.fold = null;
    this.gesture = { ...NO_GESTURE };
  }
}

const _quat = new THREE.Quaternion();
const _vec = new THREE.Vector3();
const _euler = new THREE.Euler();
const DEG = Math.PI / 180;

/**
 * Wraps the two WebXR input slots. Controllers and tracked hands are handled
 * through the same interface: `trigger` maps to the analog trigger or a pinch,
 * `squeeze` to the grip button.
 */
export class XRInput {
  readonly controllers: ControllerState[] = [];

  constructor(renderer: THREE.WebGLRenderer, parent: THREE.Object3D) {
    for (let i = 0; i < 2; i++) {
      const targetRay = renderer.xr.getController(i);
      const grip = renderer.xr.getControllerGrip(i);
      const hand = renderer.xr.getHand(i);
      parent.add(targetRay, grip, hand);

      const state = new ControllerState(i, targetRay, grip, hand);
      state.hold.name = `hold-${i}`;
      updateHold(state);
      this.controllers.push(state);

      targetRay.addEventListener('connected', (event) => {
        const source = (event as unknown as { data: XRInputSource }).data;
        state.inputSource = source;
        state.connected = true;
        state.isHand = Boolean(source.hand);
        state.handedness = source.handedness === 'left' ? 'left' : 'right';
      });

      targetRay.addEventListener('disconnected', () => state.reset());

      targetRay.addEventListener('selectstart', () => {
        state.select.press();
        if (!state.isHand) state.trigger.press();
      });
      targetRay.addEventListener('selectend', () => {
        state.select.release();
        if (!state.isHand) state.trigger.release();
      });
      targetRay.addEventListener('squeezestart', () => state.squeeze.press());
      targetRay.addEventListener('squeezeend', () => state.squeeze.release());

      // Hand tracking has no buttons at all; `readHand` below makes the two
      // gestures out of the joints every frame. Pinch stays as the generic
      // `select` (that is what the runtime raises it for) and nothing else.
    }
  }

  get(handedness: Handedness): ControllerState | null {
    return this.controllers.find((c) => c.connected && c.handedness === handedness) ?? null;
  }

  /** Call once per frame, before world updates. */
  update(): void {
    for (const state of this.controllers) {
      // A bare hand has no buttons to poll, so its two are made here — before
      // the edges are taken, so a fold that closed this frame counts as a
      // press exactly like a button would.
      if (state.isHand) readHand(state);

      // Und hierhin gehört, was diese Hand trägt: an den Griffraum des
      // Controllers, an den gedrehten Strahl einer bloßen Hand.
      updateHold(state);

      state.trigger.beginFrame();
      state.squeeze.beginFrame();
      state.select.beginFrame();
      state.primary.beginFrame();
      state.secondary.beginFrame();
      state.stick.beginFrame();
      state.menu.beginFrame();

      const gamepad = state.inputSource?.gamepad;
      if (!gamepad) {
        state.thumbstick.set(0, 0);
        continue;
      }

      // xr-standard mapping: 0 trigger, 1 squeeze, 3 thumbstick, 4/5 A/B.
      state.trigger.value = gamepad.buttons[0]?.value ?? 0;
      state.squeeze.value = gamepad.buttons[1]?.value ?? 0;
      syncFromGamepad(state.primary, gamepad.buttons[4]);
      syncFromGamepad(state.secondary, gamepad.buttons[5]);
      syncFromGamepad(state.stick, gamepad.buttons[3]);
      syncFromGamepad(state.menu, gamepad.buttons[MENU_BUTTON]);

      const axes = gamepad.axes;
      const x = axes.length >= 4 ? axes[2] : (axes[0] ?? 0);
      const y = axes.length >= 4 ? axes[3] : (axes[1] ?? 0);
      state.thumbstick.set(deadzone(x ?? 0), deadzone(y ?? 0));
    }
  }
}

/**
 * Hängt den Halteraum dorthin, wo diese Eingabequelle ihre Sachen trägt, und
 * dreht ihn, wenn es eine bloße Hand ist.
 *
 * Umgehängt wird nur, wenn er woanders hängt — `add` behält die Kinder, ein
 * Werkzeug in der Faust geht also mit, wenn jemand mitten im Spiel den
 * Controller weglegt. Die Drehung steht jedes Bild neu, weil eine Hand, die
 * gerade erst verbunden ist, ihre Seite eine Frame später meldet.
 */
function updateHold(state: ControllerState): void {
  const anchor = !state.isHand && state.grip.visible ? state.grip : state.targetRay;
  if (state.hold.parent !== anchor) anchor.add(state.hold);
  if (!state.isHand || !state.handedness) {
    state.hold.quaternion.identity();
    return;
  }
  const tilt = handHoldTilt(state.handedness);
  state.hold.quaternion.setFromEuler(
    _euler.set(tilt.pitch * DEG, tilt.yaw * DEG, tilt.roll * DEG, 'XYZ'),
  );
}

/**
 * Turns a tracked hand's joints into its trigger and its grip.
 *
 * Middle, ring and little finger on the palm is **Greifen**; the index finger
 * on the palm is the **Trigger**. Both at once is a fist, which is precisely
 * what holding a pistol and firing it looks like. See `handGestures.ts` for
 * the measurement and the thresholds — everything here is the wiring.
 */
function readHand(state: ControllerState): void {
  if (!state.hand.visible) {
    state.fold = null;
    if (state.gesture.grab) state.squeeze.release();
    if (state.gesture.trigger) state.trigger.release();
    state.gesture = { ...NO_GESTURE };
    return;
  }

  state.fold = foldRatios(handJoints(state.hand));
  const next = readGesture(state.fold, state.gesture);
  if (next.grab !== state.gesture.grab) {
    if (next.grab) state.squeeze.press();
    else state.squeeze.release();
  }
  if (next.trigger !== state.gesture.trigger) {
    if (next.trigger) state.trigger.press();
    else state.trigger.release();
  }
  state.gesture = next;
}

/** The handful of joints the fold measurement needs, by their WebXR names. */
function handJoints(hand: THREE.XRHandSpace): HandJoints {
  const joints = hand.joints as Partial<Record<string, THREE.XRJointSpace>>;
  const at = (name: string): THREE.Vector3 | null => {
    const joint = joints[name];
    return joint && joint.visible ? joint.position : null;
  };
  return {
    wrist: at('wrist'),
    palmBase: at('middle-finger-metacarpal'),
    palmKnuckle: at('middle-finger-phalanx-proximal'),
    thumbTip: at('thumb-tip'),
    indexTip: at('index-finger-tip'),
    middleTip: at('middle-finger-tip'),
    ringTip: at('ring-finger-tip'),
    pinkyTip: at('pinky-finger-tip'),
  };
}

/** Polled buttons have no events, so the edges are derived here. */
function syncFromGamepad(button: ButtonState, source: GamepadButton | undefined): void {
  const pressed = source?.pressed ?? false;
  button.justPressed = pressed && !button.pressed;
  button.justReleased = !pressed && button.pressed;
  button.pressed = pressed;
  button.value = source?.value ?? (pressed ? 1 : 0);
}

function deadzone(value: number, threshold = 0.15): number {
  if (Math.abs(value) < threshold) return 0;
  return (value - Math.sign(value) * threshold) / (1 - threshold);
}
